<script setup lang="ts">
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue';
import { GraduationCap, House, BookOpen, UserRound, Bell, ArrowUpRight, ChevronRight, ChevronLeft, CalendarDays, Clock3, MapPin, ArrowRight, ChartNoAxesColumnIncreasing, ClipboardList, LibraryBig, Settings2, ShieldCheck, Database, Sun, Moon, Monitor, X, Check, RefreshCw, Search, Info, LogOut, Sparkles, CheckCheck } from 'lucide-vue-next';
import type { AcademicData, Course } from './domain/academic';
import { coursesForDay, nextCourse, weightedAverage, weekDate } from './domain/academic';
import { mockAcademicProvider } from './services/academic';
import { loadPreferences, savePreferences, clearPreferences, defaults } from './services/preferences';
const page=ref('home'), section=ref('schedule'), week=ref(9), day=ref(4), data=ref<AcademicData>({courses:[],grades:[],exams:[],source:'mock'}), loading=ref(true), error=ref('');
const prefs=ref(loadPreferences()), modal=ref(''), selected=ref<Course>(), toast=ref(''), term=ref('all'), query=ref(''), read=ref(false);
const draft=ref({name:prefs.value.name,major:prefs.value.major});
function saveProfile(){prefs.value.name=draft.value.name.trim()||'同学';prefs.value.major=draft.value.major.trim();modal.value='';notify('个人资料已保存在本机')}
const tabs=[{id:'home',name:'统一首页',icon:House},{id:'academic',name:'教务中心',icon:BookOpen},{id:'profile',name:'个人中心',icon:UserRound}];
const entries=[{id:'schedule',name:'课程表',sub:'每一节，心中有数',icon:CalendarDays,color:'blue'},{id:'grades',name:'成绩查询',sub:'看见每一步进步',icon:ChartNoAxesColumnIncreasing,color:'purple'},{id:'exams',name:'考试安排',sub:'从容准备每一场',icon:ClipboardList,color:'orange'},{id:'study',name:'学业信息',sub:'记录你的成长',icon:GraduationCap,color:'green'},{id:'calendar',name:'学校校历',sub:'重要日子不遗漏',icon:LibraryBig,color:'pink'},{id:'official',name:'官方教务',sub:'前往学校官方网站',icon:ArrowUpRight,color:'slate'}];
const weekdays=['一','二','三','四','五','六','日'];
const todayCourses=computed(()=>coursesForDay(data.value.courses,4,9));
// A fixed clock keeps all demo views deterministic. It is visibly marked in the UI.
const upcoming=computed(()=>nextCourse(todayCourses.value,'09:40'));
const selectedCourses=computed(()=>coursesForDay(data.value.courses,day.value,week.value));
const filteredGrades=computed(()=>data.value.grades.filter(g=>(term.value==='all'||g.term===term.value)&&g.name.includes(query.value)));
const average=computed(()=>weightedAverage(filteredGrades.value).toFixed(1));
let toastTimer:ReturnType<typeof setTimeout>;
function notify(s:string){toast.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
function go(id:string){page.value='academic';section.value=id;window.scrollTo({top:0,behavior:'smooth'})}
function nav(id:string){page.value=id;window.scrollTo({top:0})}
function details(c:Course){selected.value=c;modal.value='course'}
async function load(){loading.value=true;error.value='';try{data.value=await mockAcademicProvider.load()}catch{error.value='模拟数据加载失败，请重试。'}finally{loading.value=false}}
function reset(){if(clearPreferences()){prefs.value={...defaults};modal.value='';notify('本机个人设置已重置')}else notify('浏览器未允许清除本机设置')}
watch(prefs,p=>{if(!savePreferences(p))notify('设置未保存：浏览器存储不可用')},{deep:true});
const systemDark=ref(window.matchMedia('(prefers-color-scheme: dark)').matches);
const media=window.matchMedia('(prefers-color-scheme: dark)');
function systemChange(e:MediaQueryListEvent){systemDark.value=e.matches}
watch(()=>[prefs.value.theme,systemDark.value],()=>{document.documentElement.dataset.theme=prefs.value.theme==='system'?(systemDark.value?'dark':'light'):prefs.value.theme},{immediate:true});
let previousFocus:HTMLElement|null=null;
watch(modal,async value=>{if(value){if(value==='edit')draft.value={name:prefs.value.name,major:prefs.value.major};previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.modal-close')?.focus()}else previousFocus?.focus()});
function trapFocus(e:KeyboardEvent){const items=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button,input,select,a[href]'));if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus()}}
function escape(e:KeyboardEvent){if(e.key==='Escape')modal.value=''}
onMounted(()=>{load();media.addEventListener('change',systemChange);window.addEventListener('keydown',escape)});
onUnmounted(()=>{clearTimeout(toastTimer);media.removeEventListener('change',systemChange);window.removeEventListener('keydown',escape)});
</script>

<template>
<div class="shell" :class="{compact:prefs.compact}">
  <aside class="sidebar">
    <a class="brand" href="#" @click.prevent="nav('home')"><span class="brand-icon"><GraduationCap :size="27"/></span><span>邯郸校园<small>HANDAN CAMPUS</small></span></a>
    <div class="sidebar-label">我的校园</div>
    <nav aria-label="主导航"><button v-for="t in tabs" :key="t.id" :class="{active:page===t.id}" @click="nav(t.id)"><component :is="t.icon" :size="21"/>{{t.name}}<span v-if="page===t.id" class="nav-dot"/></button></nav>
    <div class="sidebar-bottom"><div class="open-note"><span class="mini-icon"><BookOpen :size="18"/></span><strong>为同学，由同学</strong><p>让校园里的小事，<br>变得简单一点。</p><span>独立开源项目 <ArrowUpRight :size="13"/></span></div><button class="sidebar-user" @click="nav('profile')"><span class="avatar">{{prefs.name.slice(0,1)}}</span><span>{{prefs.name}}<small>本地体验账号</small></span><Settings2 :size="17"/></button></div>
  </aside>
  <div class="workspace">
    <header class="topbar"><span class="breadcrumb">我的校园 <ChevronRight :size="14"/> <strong>{{tabs.find(t=>t.id===page)?.name}}</strong></span><span class="mobile-brand"><GraduationCap :size="23"/> 邯郸校园</span><div class="header-actions"><span class="demo-pill"><span/>模拟数据体验</span><button aria-label="查看通知" class="icon-button bell" @click="modal='notifications'"><Bell :size="21"/><i v-if="!read"/></button><button class="avatar small-avatar" aria-label="个人中心" @click="nav('profile')">{{prefs.name.slice(0,1)}}</button></div></header>
    <main>
      <div v-if="loading" class="panel state"><RefreshCw/>正在准备你的校园…</div>
      <div v-else-if="error" class="panel state">{{error}}<button class="primary" @click="load">重新加载</button></div>
      <Transition v-else name="page" mode="out-in">
      <div v-if="page==='home'" key="home">
        <section class="page-heading"><div><div class="eyebrow">A LITTLE MORE ORGANIZED</div><h1>上午好，{{prefs.name}}<span class="greeting-sun">☀</span></h1><p>新的一天，从容开启你的校园生活。</p></div><div class="date-note"><CalendarDays :size="17"/><span>11月5日 · 星期四（演示）<small>2026–2027 学年 · 秋季学期</small></span></div></section>
        <section class="hero"><div class="hero-copy"><span class="hero-badge"><span/> 学期进行中</span><h2>把时间留给<br>更有意义的事。</h2><p>课程、考试、学业，你关心的都在这里。</p><button @click="go('schedule')">查看我的课表 <ArrowRight :size="17"/></button></div><div class="campus-art" aria-hidden="true"><div class="orbit orbit-one"/><div class="orbit orbit-two"/><div class="art-sun"/><div class="float-label"><GraduationCap :size="19"/> 知行合一 · 学以致用</div><div class="building back-building"><div v-for="i in 12" :key="i"/></div><div class="building main-building"><div class="building-roof"/><div class="building-name">邯 郸 学 院</div><div class="windows"><span v-for="i in 24" :key="i"/></div><div class="building-door"/></div><div class="tree tree-one"/><div class="tree tree-two"/><div class="art-ground"/></div></section>
        <section class="stats-row"><div class="stat"><span class="stat-icon blue"><CalendarDays/></span><div><small>当前教学周</small><strong>第 9 <em>周 · 模拟</em></strong></div><span class="stat-meta">共 18 周</span></div><div class="stat"><span class="stat-icon purple"><BookOpen/></span><div><small>今日课程</small><strong>{{todayCourses.length}} <em>节课程</em></strong></div><span class="stat-meta">充实的一天</span></div><div class="stat"><span class="stat-icon orange"><Clock3/></span><div><small>下一节开始</small><strong>10:00</strong></div><span class="stat-meta">演示时钟 09:40</span></div></section>
        <section class="section-block"><div class="section-heading"><h2>常用服务 <span>学习的事，轻松一点</span></h2><button class="text-button" @click="go('schedule')">全部教务 <ArrowUpRight :size="16"/></button></div><div class="quick-grid"><button v-for="e in entries" :key="e.id" class="quick-entry" @click="go(e.id)"><span class="entry-icon" :class="e.color"><component :is="e.icon" :size="23"/></span><strong>{{e.name}}</strong><small>{{e.sub}}</small><ArrowUpRight class="entry-arrow" :size="16"/></button></div></section>
        <div class="home-bottom"><section class="panel courses-panel"><div class="section-heading"><h2>今日课程 <span class="count">{{todayCourses.length}}</span></h2><button class="text-button" @click="go('schedule')">完整课表 <ChevronRight :size="16"/></button></div><button v-for="(c,i) in todayCourses" :key="c.id" class="today-course" :class="{finished:i===0}" @click="details(c)"><div class="time-col"><strong>{{c.start}}</strong><small>{{c.end}}</small></div><span class="course-line" :class="c.color"/><div class="course-info"><h3>{{c.name}} <span v-if="c.id===upcoming?.id" class="next-tag">下一节</span><span v-else-if="i===0" class="ended-tag">已结束</span></h3><p><MapPin :size="13"/>{{c.room}} <span class="teacher">· {{c.teacher}}</span></p></div><span class="period">{{c.period}}</span><ChevronRight :size="16"/></button></section><section class="panel semester-panel"><span class="semester-graphic"><Sparkles :size="25"/></span><span class="eyebrow">YOUR SEMESTER</span><h2>每一步，都算数。</h2><p>本学期已走过 <strong>9</strong> 周，<br>保持自己的节奏，继续向前。</p><div class="progress"><span/></div><div class="progress-label"><span>学期进度</span><strong>50%</strong></div><button class="text-button" @click="go('calendar')">看看学期安排 <ArrowRight :size="16"/></button></section></div>
      </div>
      <div v-else-if="page==='academic'" key="academic">
        <section class="page-heading"><div><div class="eyebrow">LEARNING, MADE SIMPLE</div><h1>教务中心</h1><p>学习的每个环节，都井然有序。</p></div><span class="data-note"><ShieldCheck :size="15"/> 当前所有教务信息均为模拟</span></section>
        <div class="academic-tabs" aria-label="教务功能"><button v-for="e in entries" :key="e.id" :class="{selected:section===e.id}" @click="section=e.id"><component :is="e.icon" :size="17"/>{{e.name}}</button></div>
        <section v-if="section==='schedule'" class="panel timetable-panel"><div class="section-heading"><div><h2>我的课程表</h2><p class="muted">2026–2027 秋季学期 · 模拟课表</p></div><div class="week-switch"><button aria-label="上一周" :disabled="week<=1" @click="week--"><ChevronLeft :size="18"/></button><strong>第 {{week}} 周</strong><button aria-label="下一周" :disabled="week>=18" @click="week++"><ChevronRight :size="18"/></button><button class="text-button" @click="week=9;day=4">本周</button></div></div><div class="week-days"><button v-for="(d,i) in weekdays" :key="d" :class="{selected:day===i+1}" @click="day=i+1"><small>周{{d}}</small><strong>{{weekDate(week,i+1)}}</strong><span v-if="i===3&&week===9" class="today-dot"/></button></div><div class="schedule-layout"><div class="day-agenda"><h3>周{{weekdays[day-1]}}的安排 <span>{{selectedCourses.length}} 节课程</span></h3><button v-for="c in selectedCourses" :key="c.id" class="agenda-course" :class="c.color" @click="details(c)"><div><strong>{{c.start}}</strong><small>{{c.end}}</small></div><section><h3>{{c.name}}</h3><p>{{c.room}} · {{c.teacher}}</p><small>{{c.period}}</small></section><ChevronRight :size="18"/></button><div v-if="!selectedCourses.length" class="empty"><Sun :size="36"/><h3>今天没有课程</h3><p>留一点时间，探索课本以外的世界。</p></div></div><div class="week-overview"><h3>本周概览</h3><div v-for="(d,i) in weekdays.slice(0,5)" :key="d" class="overview-row"><span>周{{d}}</span><div><span v-for="c in coursesForDay(data.courses,i+1,week)" :key="c.id" :class="c.color">{{c.name}}</span></div></div><p class="muted">点击日期查看当天安排，点击课程查看详情。</p></div></div></section>
        <section v-else-if="section==='grades'" class="panel"><div class="section-heading"><div><h2>成绩查询</h2><p class="muted">成绩与学分均为演示内容</p></div><select v-model="term" aria-label="筛选学期"><option value="all">全部学期</option><option>2025–2026 春季</option><option>2025–2026 秋季</option></select></div><div class="grade-stats"><div><small>加权平均分</small><strong>{{average}}</strong></div><div><small>已获学分（当前筛选）</small><strong>{{filteredGrades.reduce((s,g)=>s+g.credit,0)}}</strong></div><div><small>通过课程</small><strong>{{filteredGrades.filter(g=>g.score>=60).length}}<em> / {{filteredGrades.length}}</em></strong></div></div><label class="search"><Search :size="18"/><input v-model="query" placeholder="搜索课程名称" aria-label="搜索课程名称"/></label><div class="grade-list"><div v-for="g in filteredGrades" :key="g.name" class="grade-row"><span class="entry-icon blue"><BookOpen :size="20"/></span><div><h3>{{g.name}}</h3><small>{{g.term}} · {{g.kind}} · {{g.credit}} 学分</small></div><strong>{{g.score}}<small>分</small></strong></div><div v-if="!filteredGrades.length" class="empty">没有找到匹配的课程</div></div><p class="muted">加权平均分 = Σ（成绩 × 学分）/ Σ学分；暂不推算学校官方 GPA。</p></section>
        <section v-else-if="section==='exams'" class="panel"><div class="section-heading"><h2>考试安排</h2><span class="soft-pill">{{data.exams.length}} 场模拟考试</span></div><div class="exam-list"><article v-for="(e,i) in data.exams" :key="e.name" class="exam-card"><span class="exam-number">0{{i+1}}</span><div><h3>{{e.name}}</h3><p><CalendarDays :size="15"/>{{e.date}} · {{e.time}}</p><p><MapPin :size="15"/>{{e.room}} · 座位 {{e.seat}}</p></div><span class="soft-pill">期末考试</span></article></div><div class="inline-note"><Info :size="17"/>实际考试时间、地点请以学校发布的信息为准。</div></section>
        <section v-else-if="section==='study'" class="panel"><h2>学业信息</h2><p class="muted">模拟培养方案 · 非官方毕业资格判断</p><div class="study-summary"><GraduationCap :size="43"/><div><h3>{{prefs.major}}</h3><p>四年制本科 · 演示学籍</p></div></div><div class="credit-block" v-for="c in [{name:'通识教育',done:28,total:40},{name:'专业教育',done:52,total:90},{name:'实践教学',done:12,total:30}]" :key="c.name"><div><strong>{{c.name}}</strong><span>{{c.done}} / {{c.total}} 学分</span></div><div class="progress"><span :style="{width:c.done/c.total*100+'%'}"/></div></div><p class="inline-note">学分进度为独立模拟示例，与成绩页的演示课程不构成完整对应。</p></section>
        <section v-else-if="section==='calendar'" class="panel"><div class="section-heading"><div><h2>学期校历</h2><p class="muted">演示学期：2026年9月7日开始，共18周</p></div><span class="soft-pill">模拟校历</span></div><div class="calendar-grid"><button v-for="w in 18" :key="w" :class="{current:w===9}" @click="week=w;section='schedule'"><small>第 {{w}} 周</small><strong>{{weekDate(w,1)}}</strong><span>{{w===9?'演示当前周':w>=17?'模拟考试周':'教学周'}}</span></button></div><p class="inline-note"><Info :size="17"/>本校历不是邯郸学院官方校历，不用于实际教学安排。</p></section>
        <section v-else class="panel official-panel"><span class="entry-icon blue"><LibraryBig :size="30"/></span><h2>连接官方，获取准确信息。</h2><p>在学校官方网站查询正式教务信息。<br>本应用不会读取或保存你在学校网站输入的账号与密码。</p><a href="https://jwgl.hdc.edu.cn/xtgl/login_slogin.html" target="_blank" rel="noopener noreferrer" class="official-link"><span><strong>教学综合信息服务平台</strong><small>jwgl.hdc.edu.cn</small></span><ArrowUpRight :size="22"/></a><a href="https://www.hdc.edu.cn/" target="_blank" rel="noopener noreferrer" class="official-link"><span><strong>邯郸学院官方网站</strong><small>www.hdc.edu.cn</small></span><ArrowUpRight :size="22"/></a><p class="muted">链接将于外部浏览器打开；能否访问取决于学校网络服务。</p></section>
      </div>
      <div v-else key="profile">
        <section class="page-heading"><div><div class="eyebrow">A SPACE OF YOUR OWN</div><h1>个人中心</h1><p>让校园助手，更合你的习惯。</p></div></section>
        <div class="profile-layout"><section class="panel profile-card"><span class="avatar profile-avatar">{{prefs.name.slice(0,1)}}</span><h2>{{prefs.name}}</h2><p>{{prefs.major}}</p><span class="soft-pill">模拟学生 · 本地体验账号</span><button class="primary" @click="modal='edit'">编辑个人资料</button><div class="profile-privacy"><ShieldCheck :size="18"/>资料仅保存在当前浏览器</div></section><div class="settings-stack"><section class="panel"><h2>外观与体验</h2><div class="setting-title"><Sun :size="19"/><span>主题设置<small>选择你喜欢的校园底色</small></span></div><div class="theme-options"><button v-for="t in [{id:'light',name:'浅色',icon:Sun},{id:'dark',name:'深色',icon:Moon},{id:'system',name:'跟随系统',icon:Monitor}]" :key="t.id" :class="{selected:prefs.theme===t.id}" @click="prefs.theme=t.id as typeof prefs.theme"><component :is="t.icon" :size="20"/>{{t.name}}<Check v-if="prefs.theme===t.id" :size="15"/></button></div><label class="setting-row"><span><strong>紧凑布局</strong><small>减少卡片留白，浏览更多内容</small></span><input type="checkbox" class="switch" v-model="prefs.compact"/></label></section><section class="panel"><h2>通知与数据</h2><label class="setting-row"><span><strong>应用内提醒</strong><small>仅控制演示提醒，不发送系统推送</small></span><input type="checkbox" class="switch" v-model="prefs.notifications"/></label><button class="setting-row" @click="modal='notifications'"><span class="setting-icon"><Bell :size="19"/><strong>通知中心</strong></span><ChevronRight :size="18"/></button><button class="setting-row" @click="modal='cache'"><span class="setting-icon"><Database :size="19"/><span><strong>缓存管理</strong><small>查看当前数据存储状态</small></span></span><ChevronRight :size="18"/></button><button class="setting-row" @click="modal='reset'"><span class="setting-icon"><Database :size="19"/><span><strong>重置本机设置</strong><small>清除昵称、主题和偏好；演示课程不受影响</small></span></span><ChevronRight :size="18"/></button><button class="setting-row" @click="modal='privacy'"><span class="setting-icon"><ShieldCheck :size="19"/><strong>隐私说明</strong></span><ChevronRight :size="18"/></button><button class="setting-row" @click="modal='about'"><span class="setting-icon"><Info :size="19"/><strong>关于邯郸校园</strong></span><span class="muted">v0.1.0 <ChevronRight :size="15"/></span></button></section></div></div>
      </div>
      </Transition>
      <footer><span class="footer-mark"><GraduationCap :size="16"/> 邯郸校园</span><span>为每一天的校园生活，减一点繁琐。</span><small>独立学生项目 · 非学校官方应用 · 所有教务数据均为模拟</small></footer>
    </main>
  </div>
  <nav class="bottom-nav" aria-label="手机主导航"><button v-for="t in tabs" :key="t.id" :class="{active:page===t.id}" @click="nav(t.id)"><component :is="t.icon" :size="22"/><span>{{t.name}}</span></button></nav>
  <Transition name="toast"><div v-if="toast" class="toast" role="status"><Check :size="17"/>{{toast}}</div></Transition>
  <div v-if="modal" class="modal-overlay" @click.self="modal=''" @keydown.tab="trapFocus"><section class="modal panel" role="dialog" aria-modal="true" :aria-label="modal==='course'?'课程详情':'校园助手设置'"><button class="modal-close icon-button" aria-label="关闭" @click="modal=''"><X :size="22"/></button>
    <template v-if="modal==='course'&&selected"><span class="entry-icon" :class="selected.color"><BookOpen :size="25"/></span><h2>{{selected.name}}</h2><p class="muted">课程详情 · 模拟数据</p><dl><dt>上课时间</dt><dd>周{{weekdays[selected.day-1]}} {{selected.start}}–{{selected.end}}</dd><dt>节次</dt><dd>{{selected.period}}</dd><dt>教室</dt><dd>{{selected.room}}</dd><dt>教师</dt><dd>{{selected.teacher}}</dd><dt>教学周</dt><dd>{{selected.weeks.length===18?'1–18周':selected.weeks.join('、')+'周'}}</dd></dl><button class="primary full" @click="modal=''">知道了</button></template>
    <template v-else-if="modal==='notifications'"><h2>通知中心</h2><p class="muted">应用内演示提醒</p><div v-if="!prefs.notifications" class="empty"><Bell/><h3>应用内提醒已关闭</h3><p>可在个人中心重新开启。</p></div><template v-else><article class="notice"><span class="entry-icon blue"><Info :size="21"/></span><div><h3>欢迎体验邯郸校园</h3><p>当前课程、成绩、考试与校历均为模拟。你可以放心探索，无需输入学校账号。</p><small>项目公告 · {{read?'已读':'未读'}}</small></div></article><button class="primary full" @click="read=true;notify('通知已标记为已读')"><CheckCheck :size="17"/>全部标为已读</button></template></template>
    <form v-else-if="modal==='edit'" @submit.prevent="saveProfile"><h2>编辑个人资料</h2><p class="muted">请使用昵称，无需填写真实学号或身份信息。</p><label class="form-label">昵称<input v-model="draft.name" maxlength="20" required placeholder="怎么称呼你"/></label><label class="form-label">专业 / 年级<input v-model="draft.major" maxlength="50" required/></label><button class="primary full" type="submit">保存资料</button></form>
    <template v-else-if="modal==='cache'"><Database :size="30"/><h2>缓存管理</h2><p>当前版本没有离线教务缓存，也未下载学校数据。演示数据随应用资源提供，加载后只保留在内存中。</p><p>个人资料和偏好单独保存在本机，可以通过“重置本机设置”清除。</p><button class="primary full" @click="load();modal='';notify('演示数据已重新加载')"><RefreshCw :size="16"/>重新加载演示数据</button></template><template v-else-if="modal==='reset'"><Database :size="30"/><h2>重置本机设置？</h2><p>将恢复默认昵称、主题和偏好。模拟教务数据会继续提供。</p><div class="modal-actions"><button @click="modal=''">取消</button><button class="primary" @click="reset">确认重置</button></div></template>
    <template v-else-if="modal==='privacy'"><ShieldCheck :size="30"/><h2>你的数据，由你掌握。</h2><p>本版本不连接学校教务系统，不采集学校账号、密码、学号，不包含分析或广告追踪代码。</p><p>昵称、专业和偏好存储于当前浏览器 localStorage，可随时重置。课程、成绩、考试和学业进度都是虚构示例。</p><p>托管平台可能产生运行必需的访问日志。外部官方链接受对应网站的隐私政策约束。</p><button class="primary full" @click="modal=''">我知道了</button></template>
    <template v-else><span class="brand-icon"><GraduationCap :size="29"/></span><h2>邯郸校园 <small>v0.1.0</small></h2><p>为同学，由同学。一个独立、开源的校园助手，尚未获得邯郸学院官方认证或合作授权。</p><p>设计与工程研究参考 UBAA、HFUT-Schedule、DanXi 和 fzuhelper-app。应用代码独立实现，采用 MIT 许可证。</p><p class="muted">Vue 3 · TypeScript · Vite · Capacitor</p></template>
  </section></div>
</div>
</template>
